import * as Phaser from "phaser";
import { hasImage } from "./assets";
import { hex } from "./color";

export function backdrop(scene: Phaser.Scene, key = "background") {
  const { width, height } = scene.scale;
  if (hasImage(key)) {
    const image = scene.add.image(width / 2, height / 2, key).setScrollFactor(0).setDepth(-100);
    const scale = Math.max(width / image.width, height / image.height);
    image.setScale(scale);
    scene.tweens.add({ targets: image, scale: scale * 1.04, duration: 14_000, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
  } else {
    const g = scene.add.graphics().setScrollFactor(0).setDepth(-100);
    g.fillGradientStyle(hex("backgroundAlt"), hex("backgroundAlt"), hex("background"), hex("background"), 1).fillRect(0, 0, width, height);
    for (const [x, y, color] of [
      [0.18, 0.25, "primary"],
      [0.82, 0.7, "secondary"],
    ] as const) {
      const glow = scene.add.image(width * x, height * y, "glow").setTint(hex(color)).setBlendMode(Phaser.BlendModes.ADD).setScale(4).setAlpha(0.35).setDepth(-99);
      scene.tweens.add({ targets: glow, x: glow.x + 40, y: glow.y - 30, duration: 9_000, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
    }
  }
  scene.add
    .particles(0, 0, "dot", {
      x: { min: 0, max: width },
      y: height + 10,
      speedY: { min: -40, max: -12 },
      speedX: { min: -8, max: 8 },
      lifespan: 14_000,
      scale: { min: 0.15, max: 0.45 },
      alpha: { start: 0.55, end: 0 },
      tint: [hex("primary"), hex("secondary"), hex("text")],
      blendMode: Phaser.BlendModes.ADD,
      frequency: 220,
      advance: 12_000,
    })
    .setDepth(-98)
    .setScrollFactor(0);
}

game2d.game/controls.ts:
import * as Phaser from "phaser";
import { HUD_DEPTH } from "./look";
import { hex } from "./color";

type KeyName = "W" | "A" | "S" | "D" | "UP" | "DOWN" | "LEFT" | "RIGHT" | "SPACE" | "ENTER" | "Z" | "P" | "ESC";

export type Controls = {
  readonly x: number;
  readonly y: number;
  readonly action: boolean;
  readonly actionPressed: boolean;
  readonly pausePressed: boolean;
  readonly touch: boolean;
  update(): void;
};

const JOYSTICK_RADIUS = 70;

export function createControls(scene: Phaser.Scene): Controls {
  const keyboard = scene.input.keyboard;
  const keys = (keyboard?.addKeys("W,A,S,D,UP,DOWN,LEFT,RIGHT,SPACE,ENTER,Z,P,ESC") ?? {}) as Partial<Record<KeyName, Phaser.Input.Keyboard.Key>>;
  const touch = scene.sys.game.device.input.touch;
  const down = (...names: KeyName[]) => names.some((n) => keys[n]?.isDown);
  const justDown = (...names: KeyName[]) => names.some((n) => (keys[n] ? Phaser.Input.Keyboard.JustDown(keys[n]) : false));

  const stick = { id: -1, ox: 0, oy: 0, x: 0, y: 0 };
  let touchAction = false;
  let touchActionPressed = false;
  const { width, height } = scene.scale;
  const button = { x: width - 110, y: height - 110, r: 58 };
  const overlay = touch ? scene.add.graphics().setScrollFactor(0).setDepth(HUD_DEPTH + 1_000) : null;

  if (touch) {
    scene.input.addPointer(2);
    scene.input.on("pointerdown", (p: Phaser.Input.Pointer) => {
      if (Phaser.Math.Distance.Between(p.x, p.y, button.x, button.y) < button.r * 1.4) {
        touchAction = true;
        touchActionPressed = true;
      } else if (p.x < width * 0.6 && stick.id === -1) {
        Object.assign(stick, { id: p.id, ox: p.x, oy: p.y, x: 0, y: 0 });
      }
    });
    scene.input.on("pointermove", (p: Phaser.Input.Pointer) => {
      if (p.id !== stick.id) return;
      const dx = p.x - stick.ox;
      const dy = p.y - stick.oy;
      const length = Math.max(1, Math.hypot(dx, dy));
      const k = Math.min(1, length / JOYSTICK_RADIUS);
      stick.x = (dx / length) * k;
      stick.y = (dy / length) * k;
    });
    scene.input.on("pointerup", (p: Phaser.Input.Pointer) => {
      if (p.id === stick.id) Object.assign(stick, { id: -1, x: 0, y: 0 });
      else touchAction = false;
    });
  }

  const state = { x: 0, y: 0, action: false, actionPressed: false, pausePressed: false };

  return {
    get x() {
      return state.x;
    },
    get y() {
      return state.y;
    },
    get action() {
      return state.action;
    },
    get actionPressed() {
      return state.actionPressed;
    },
    get pausePressed() {
      return state.pausePressed;
    },
    touch,
    update() {
      const kx = (down("RIGHT", "D") ? 1 : 0) - (down("LEFT", "A") ? 1 : 0);
      const ky = (down("DOWN", "S") ? 1 : 0) - (down("UP", "W") ? 1 : 0);
      const length = Math.hypot(kx, ky) || 1;
      state.x = kx ? kx / length : stick.x;
      state.y = ky ? ky / length : stick.y;
      state.action = down("SPACE", "Z", "ENTER") || touchAction;
      state.actionPressed = justDown("SPACE", "Z", "ENTER") || touchActionPressed;
      state.pausePressed = justDown("P", "ESC");
      touchActionPressed = false;
      if (overlay) {
        overlay.clear();
        overlay.fillStyle(hex("text"), touchAction ? 0.35 : 0.18).fillCircle(button.x, button.y, button.r);
        overlay.lineStyle(4, hex("text"), 0.5).strokeCircle(button.x, button.y, button.r);
        if (stick.id !== -1) {
          overlay.fillStyle(hex("text"), 0.12).fillCircle(stick.ox, stick.oy, JOYSTICK_RADIUS);
          overlay.fillStyle(hex("text"), 0.45).fillCircle(stick.ox + stick.x * JOYSTICK_RADIUS, stick.oy + stick.y * JOYSTICK_RADIUS, 30);
        }
      }
    },
  };
}

game2d.game/juice.ts:
import * as Phaser from "phaser";
import { hex, type PaletteColor, rgb } from "./color";
import { font } from "./fonts";
import { LOOK, PALETTE } from "./palette";

export type Strength = "light" | "medium" | "heavy";

const SHAKE: Record<Strength, [number, number]> = { light: [90, 0.003], medium: [160, 0.007], heavy: [280, 0.013] };

export function shake(scene: Phaser.Scene, strength: Strength = "light") {
  const [duration, intensity] = SHAKE[strength];
  scene.cameras.main.shake(duration, intensity);
}

export function flash(scene: Phaser.Scene, color: PaletteColor = "text", duration = 90) {
  const [r, g, b] = rgb(color);
  scene.cameras.main.flash(duration, r, g, b);
}

export function hitStop(scene: Phaser.Scene, ms = 60) {
  if (scene.data.get("hitStop")) return;
  scene.data.set("hitStop", true);
  scene.physics.world.pause();
  scene.tweens.timeScale = 0;
  scene.time.timeScale = 0;
  window.setTimeout(() => {
    scene.physics.world.resume();
    scene.tweens.timeScale = 1;
    scene.time.timeScale = 1;
    scene.data.set("hitStop", false);
  }, ms);
}

export function popText(scene: Phaser.Scene, x: number, y: number, text: string, color: PaletteColor = "accent", size = 34) {
  const label = scene.add
    .text(x, y, text, { fontFamily: font("display"), fontSize: `${size}px`, fontStyle: "700", color: PALETTE[color] })
    .setOrigin(0.5)
    .setStroke(PALETTE.outline, Math.max(2, LOOK.outline))
    .setDepth(5_000)
    .setScale(0.4);
  scene.tweens.add({ targets: label, scale: 1, duration: 140, ease: "Back.easeOut" });
  scene.tweens.add({ targets: label, y: y - 70, alpha: 0, delay: 260, duration: 520, ease: "Quad.easeIn", onComplete: () => label.destroy() });
  return label;
}

export function squash(target: Phaser.GameObjects.Components.Transform & Phaser.GameObjects.GameObject, x = 1.25, y = 0.8, duration = 90) {
  const scene = target.scene;
  const sx = target.scaleX;
  const sy = target.scaleY;
  scene.tweens.add({ targets: target, scaleX: sx * x, scaleY: sy * y, duration, yoyo: true, ease: "Quad.easeOut", onComplete: () => target.setScale(sx, sy) });
}

export type BurstOptions = { color?: PaletteColor | PaletteColor[]; count?: number; speed?: [number, number]; lifespan?: number; scale?: number; texture?: string; gravity?: number };

export function burst(scene: Phaser.Scene, x: number, y: number, options: BurstOptions = {}) {
  const colors = ([] as PaletteColor[]).concat(options.color ?? ["primary", "accent"]);
  const [min, max] = options.speed ?? [90, 320];
  const lifespan = options.lifespan ?? 520;
  const emitter = scene.add.particles(x, y, options.texture ?? "spark", {
    speed: { min, max },
    angle: { min: 0, max: 360 },
    lifespan: { min: lifespan * 0.6, max: lifespan },
    scale: { start: options.scale ?? 0.9, end: 0 },
    alpha: { start: 1, end: 0 },
    tint: colors.map(hex),
    gravityY: options.gravity ?? 0,
    blendMode: Phaser.BlendModes.ADD,
    emitting: false,
  });
  emitter.setDepth(4_000);
  emitter.explode(options.count ?? 18);
  scene.time.delayedCall(lifespan + 100, () => emitter.destroy());
  return emitter;
}

export function trail(scene: Phaser.Scene, target: Phaser.GameObjects.GameObject & { x: number; y: number }, color: PaletteColor = "primary") {
  const emitter = scene.add.particles(0, 0, "spark", {
    follow: target,
    speed: { min: 0, max: 30 },
    lifespan: 380,
    scale: { start: 0.55, end: 0 },
    alpha: { start: 0.7, end: 0 },
    tint: hex(color),
    blendMode: Phaser.BlendModes.ADD,
    frequency: 24,
  });
  emitter.setDepth(-1);
  return emitter;
}

export function float(target: Phaser.GameObjects.GameObject & { y: number }, amount = 8, duration = 1600) {
  return target.scene.tweens.add({ targets: target, y: target.y - amount, duration, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
}

export function pulse(target: Phaser.GameObjects.GameObject, scale = 1.08, duration = 700) {
  return target.scene.tweens.add({ targets: target, scale, duration, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
}

export function go(scene: Phaser.Scene, key: string, data?: object, duration = 260) {
  const [r, g, b] = rgb("background");
  scene.cameras.main.fadeOut(duration, r, g, b);
  scene.cameras.main.once(Phaser.Cameras.Scene2D.Events.FADE_OUT_COMPLETE, () => scene.scene.start(key, data));
}

export function arrive(scene: Phaser.Scene, duration = 260) {
  const [r, g, b] = rgb("background");
  scene.cameras.main.fadeIn(duration, r, g, b);
}

game2d.game/look.ts:
import * as Phaser from "phaser";
import { hex } from "./color";
import { LOOK } from "./palette";

export const HUD_DEPTH = 9_000;

type Layered = Phaser.GameObjects.GameObject & { depth: number };

export function applyLook(scene: Phaser.Scene) {
  const main = scene.cameras.main;
  const hud = scene.cameras.add(0, 0, scene.scale.width, scene.scale.height, false, "hud");
  scene.events.on(Phaser.Scenes.Events.POST_UPDATE, () => {
    for (const child of scene.children.list as Layered[]) child.cameraFilter = child.depth >= HUD_DEPTH ? main.id : hud.id;
  });
  if (scene.sys.renderer.type !== Phaser.WEBGL) return;
  const grade = main.filters.internal.addColorMatrix();
  grade.colorMatrix.saturate(LOOK.saturation - 1, true);
  grade.colorMatrix.contrast(LOOK.contrast - 1, true);
  if (LOOK.bloom > 0) {
    Phaser.Actions.AddEffectBloom(main, { threshold: LOOK.bloomThreshold, blendAmount: LOOK.bloom, blurRadius: 3, blurSteps: 4, blurQuality: 1 });
  }
  if (LOOK.vignette > 0) main.filters.external.addVignette(0.5, 0.5, 0.9, LOOK.vignette, hex("outline"));
}

game2d.game/main.ts:
import * as Phaser from "phaser";
import { HEIGHT, WIDTH } from "./config";
import { PALETTE, PIXEL_ART } from "./palette";
import { probe } from "./probe";
import { BootScene } from "./scenes/boot";
import { GameOverScene } from "./scenes/game-over";
import { PauseScene } from "./scenes/pause";
import { PlayScene } from "./scenes/play";
import { TitleScene } from "./scenes/title";
import { sfx } from "./sfx";

export function startGame(parent: HTMLElement) {
  sfx.init();
  const game = new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: WIDTH,
    height: HEIGHT,
    backgroundColor: PALETTE.background,
    pixelArt: PIXEL_ART,
    antialias: !PIXEL_ART,
    scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
    physics: { default: "arcade", arcade: { gravity: { x: 0, y: 0 }, debug: false } },
    input: { activePointers: 3 },
    scene: [BootScene, TitleScene, PlayScene, PauseScene, GameOverScene],
  });
  probe.attach();
  return () => game.destroy(true);
}

game2d.game/scenes/boot.ts:
import * as Phaser from "phaser";
import { IMAGE_ENTRIES, SPRITESHEET_ENTRIES } from "../assets";
import { hex } from "../color";
import { loadFonts } from "../fonts";
import { probe } from "../probe";
import { createProceduralTextures } from "../textures";

export class BootScene extends Phaser.Scene {
  constructor() {
    super("boot");
  }

  preload() {
    createProceduralTextures(this);
    const { width, height } = this.scale;
    const bar = this.add.graphics();
    this.load.on("progress", (value: number) => {
      bar.clear();
      bar.fillStyle(hex("surface"), 1).fillRoundedRect(width / 2 - 200, height / 2 - 8, 400, 16, 8);
      bar.fillStyle(hex("primary"), 1).fillRoundedRect(width / 2 - 200, height / 2 - 8, Math.max(16, 400 * value), 16, 8);
    });
    for (const [key, url] of IMAGE_ENTRIES) this.load.image(key, url);
    for (const [key, sheet] of SPRITESHEET_ENTRIES) {
      this.load.spritesheet(key, sheet.url, { frameWidth: sheet.frameWidth, frameHeight: sheet.frameHeight });
    }
  }

  create() {
    probe.set({ scene: "boot" });
    loadFonts().then(() => this.scene.start("title"));
  }
}

game2d.game/scenes/game-over.ts:
import * as Phaser from "phaser";
import { backdrop } from "../backdrop";
import { arrive, burst, float, go } from "../juice";
import { applyLook } from "../look";
import { probe } from "../probe";
import { sfx } from "../sfx";
import { bestScore, recordScore } from "../storage";
import { TEXT } from "../text";
import { button, label, menu, panel } from "../ui";

export class GameOverScene extends Phaser.Scene {
  constructor() {
    super("over");
  }

  create(data: { score?: number }) {
    const score = data.score ?? 0;
    const previous = bestScore();
    const best = recordScore(score);
    probe.set({ scene: "over", over: true, score, best });
    applyLook(this);
    backdrop(this);
    arrive(this);
    const { width, height } = this.scale;

    panel(this, width / 2, height / 2, 620, 520);
    float(label(this, width / 2, height / 2 - 190, TEXT.gameOver, { size: 72, color: "danger" }), 6, 2000);
    const shown = label(this, width / 2, height / 2 - 70, "0", { size: 96, color: "accent" });
    this.tweens.addCounter({
      from: 0,
      to: score,
      duration: Math.min(1200, 300 + score * 4),
      ease: "Quad.easeOut",
      onUpdate: (tween) => shown.setText(String(Math.round(tween.getValue() ?? 0))),
    });
    label(this, width / 2, height / 2 + 10, `${TEXT.best}: ${best}`, { size: 24, role: "body", color: "textMuted", stroke: false });
    if (score > previous && score > 0) {
      label(this, width / 2, height / 2 - 140, TEXT.newBest, { size: 28, color: "success" });
      this.time.delayedCall(500, () => {
        sfx.play("powerup");
        burst(this, width / 2, height / 2 - 70, { color: ["accent", "success", "text"], count: 50, speed: [160, 480], lifespan: 1000 });
      });
    }
    menu(this, [
      button(this, width / 2, height / 2 + 110, TEXT.playAgain, () => go(this, "play")),
      button(this, width / 2, height / 2 + 200, TEXT.toTitle, () => go(this, "title"), { color: "surface" }),
    ]);
  }
}

game2d.game/scenes/pause.ts:
import * as Phaser from "phaser";
import { hex } from "../color";
import { probe } from "../probe";
import { TEXT } from "../text";
import { button, label, menu, panel } from "../ui";

export class PauseScene extends Phaser.Scene {
  constructor() {
    super("pause");
  }

  create() {
    const { width, height } = this.scale;
    this.add.rectangle(0, 0, width, height, hex("background"), 0.6).setOrigin(0);
    panel(this, width / 2, height / 2, 520, 420);
    label(this, width / 2, height / 2 - 140, TEXT.paused, { size: 56 });
    const resume = () => {
      probe.set({ paused: false });
      this.scene.stop();
      this.scene.resume("play");
    };
    const buttons = [
      button(this, width / 2, height / 2 - 30, TEXT.resume, resume),
      button(this, width / 2, height / 2 + 60, TEXT.restart, () => {
        this.scene.stop();
        this.scene.stop("play");
        this.scene.start("play");
      }, { color: "secondary" }),
      button(this, width / 2, height / 2 + 150, TEXT.toTitle, () => {
        this.scene.stop("play");
        this.scene.start("title");
      }, { color: "surface" }),
    ];
    menu(this, buttons);
    this.input.keyboard?.once("keydown-ESC", resume);
    this.input.keyboard?.once("keydown-P", resume);
  }
}

game2d.game/scenes/play.ts:
import * as Phaser from "phaser";
import { hasImage } from "../assets";
import { backdrop } from "../backdrop";
import { hex } from "../color";
import { type Controls, createControls } from "../controls";
import { arrive, burst, flash, go, hitStop, popText, shake, squash, trail } from "../juice";
import { applyLook } from "../look";
import { probe } from "../probe";
import { sfx } from "../sfx";
import { TEXT } from "../text";
import { hudCounter } from "../ui";

const PLAYER_SIZE = 72;
const SPEED = 520;

export class PlayScene extends Phaser.Scene {
  private controls!: Controls;
  private player!: Phaser.Physics.Arcade.Image;
  private pickups!: Phaser.Physics.Arcade.Group;
  private hazards!: Phaser.Physics.Arcade.Group;
  private score = 0;
  private lives = 3;
  private combo = 0;
  private invulnerableUntil = 0;
  private elapsed = 0;
  private scoreHud!: ReturnType<typeof hudCounter>;
  private livesHud!: ReturnType<typeof hudCounter>;

  constructor() {
    super("play");
  }

  create() {
    this.score = 0;
    this.lives = 3;
    this.combo = 0;
    this.elapsed = 0;
    probe.set({ scene: "play", score: 0, lives: this.lives, over: false, paused: false });
    applyLook(this);
    backdrop(this);
    arrive(this);
    const { width, height } = this.scale;

    this.player = this.physics.add.image(width / 2, height * 0.7, hasImage("player") ? "player" : "diamond");
    if (!hasImage("player")) this.player.setTint(hex("primary"));
    this.player.setDisplaySize(PLAYER_SIZE, PLAYER_SIZE * (this.player.height / this.player.width));
    this.player.setCollideWorldBounds(true);
    this.player.body?.setCircle(this.player.width * 0.38, this.player.width * 0.12, this.player.height * 0.12);
    trail(this, this.player, "primary");

    this.pickups = this.physics.add.group();
    this.hazards = this.physics.add.group();
    this.physics.add.overlap(this.player, this.pickups, (_, pickup) => this.collect(pickup as Phaser.Physics.Arcade.Image));
    this.physics.add.overlap(this.player, this.hazards, (_, hazard) => this.hurt(hazard as Phaser.Physics.Arcade.Image));

    this.scoreHud = hudCounter(this, 32, 24, TEXT.score);
    this.livesHud = hudCounter(this, width - 32, 24, TEXT.lives, "right");
    this.livesHud.set(this.lives);

    this.controls = createControls(this);
    for (let i = 0; i < 3; i++) this.spawnPickup();
    this.time.addEvent({ delay: 900, loop: true, callback: () => this.spawnPickup() });
    this.time.addEvent({ delay: 1400, loop: true, callback: () => this.spawnHazard() });
    this.game.events.on(Phaser.Core.Events.BLUR, this.pause, this);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => this.game.events.off(Phaser.Core.Events.BLUR, this.pause, this));
    this.input.keyboard?.on("keydown-M", () => sfx.toggleMute());
  }

  update(_: number, delta: number) {
    this.controls.update();
    if (this.controls.pausePressed) return this.pause();
    this.elapsed += delta;
    const body = this.player.body as Phaser.Physics.Arcade.Body;
    const smoothing = 1 - Math.pow(0.0001, delta / 1000);
    body.setVelocity(
      Phaser.Math.Linear(body.velocity.x, this.controls.x * SPEED, smoothing),
      Phaser.Math.Linear(body.velocity.y, this.controls.y * SPEED, smoothing),
    );
    this.player.setRotation(Phaser.Math.Linear(this.player.rotation, body.velocity.x / SPEED / 4, 0.2));
    this.player.setAlpha(this.time.now < this.invulnerableUntil ? 0.45 + 0.4 * Math.sin(this.time.now / 40) : 1);
    for (const hazard of this.hazards.getChildren() as Phaser.Physics.Arcade.Image[]) {
      if (hazard.y > this.scale.height + 80) hazard.destroy();
    }
  }

  private spawnPickup() {
    const { width, height } = this.scale;
    const pickup = this.pickups.create(Phaser.Math.Between(80, width - 80), Phaser.Math.Between(120, height - 80), hasImage("pickup") ? "pickup" : "star") as Phaser.Physics.Arcade.Image;
    if (!hasImage("pickup")) pickup.setTint(hex("accent"));
    pickup.setDisplaySize(44, 44 * (pickup.height / pickup.width)).setScale(0);
    this.tweens.add({ targets: pickup, scale: 44 / pickup.width, duration: 260, ease: "Back.easeOut" });
    this.tweens.add({ targets: pickup, angle: 360, duration: 4000, repeat: -1 });
    this.time.delayedCall(6000, () => pickup.active && this.tweens.add({ targets: pickup, scale: 0, duration: 200, onComplete: () => pickup.destroy() }));
  }

  private spawnHazard() {
    const { width } = this.scale;
    const speed = 160 + Math.min(320, this.elapsed / 120);
    const hazard = this.hazards.create(Phaser.Math.Between(40, width - 40), -60, hasImage("hazard") ? "hazard" : "diamond") as Phaser.Physics.Arcade.Image;
    if (!hasImage("hazard")) hazard.setTint(hex("danger"));
    hazard.setDisplaySize(58, 58 * (hazard.height / hazard.width)).setVelocity(Phaser.Math.Between(-60, 60), speed).setAngularVelocity(Phaser.Math.Between(-120, 120));
  }

  private collect(pickup: Phaser.Physics.Arcade.Image) {
    const points = 10 * (1 + Math.min(4, this.combo));
    this.combo += 1;
    this.score += points;
    this.scoreHud.set(this.score);
    probe.set({ score: this.score });
    sfx.play("pickup", 1 + Math.min(0.5, this.combo * 0.06));
    burst(this, pickup.x, pickup.y, { color: ["accent", "text"], count: 16 });
    popText(this, pickup.x, pickup.y - 20, `+${points}`);
    squash(this.player, 1.2, 0.85);
    pickup.destroy();
  }

  private hurt(hazard: Phaser.Physics.Arcade.Image) {
    if (this.time.now < this.invulnerableUntil) return;
    this.lives -= 1;
    this.combo = 0;
    this.livesHud.set(this.lives);
    probe.set({ lives: this.lives });
    burst(this, hazard.x, hazard.y, { color: ["danger", "accent"], count: 26, speed: [140, 420] });
    hazard.destroy();
    if (this.lives <= 0) return this.lose();
    this.invulnerableUntil = this.time.now + 1200;
    sfx.play("hit");
    shake(this, "medium");
    flash(this, "danger", 110);
    hitStop(this, 70);
  }

  private lose() {
    sfx.play("lose");
    shake(this, "heavy");
    flash(this, "danger", 200);
    burst(this, this.player.x, this.player.y, { color: ["primary", "danger", "text"], count: 60, speed: [160, 560], lifespan: 900 });
    this.player.setVisible(false);
    this.physics.pause();
    probe.set({ over: true });
    this.time.delayedCall(700, () => go(this, "over", { score: this.score }));
  }

  private pause() {
    if (!this.scene.isActive() || probe.state.over) return;
    probe.set({ paused: true });
    this.scene.pause();
    this.scene.launch("pause");
  }
}

