rules.no-comments.mjs:
const KEPT = /^\s*(eslint-disable|eslint-enable|eslint\s|global\s|@ts-expect-error|prettier-ignore)/;
const TRIPLE_SLASH = /^\/\s*<reference\s/;

function lineBounds(text, start, end) {
  const lineStart = text.lastIndexOf("\n", start - 1) + 1;
  const newline = text.indexOf("\n", end);
  const lineEnd = newline === -1 ? text.length : newline + 1;
  return { lineStart, lineEnd };
}

function removalRange(sourceCode, start, end) {
  const text = sourceCode.text;
  const { lineStart, lineEnd } = lineBounds(text, start, end);
  const before = text.slice(lineStart, start);
  const after = text.slice(end, lineEnd);
  if (!before.trim() && !after.trim()) return [lineStart, lineEnd];
  if (!after.trim()) return [start - (before.length - before.trimEnd().length), end];
  return [start, end];
}

const rule = {
  meta: {
    type: "suggestion",
    fixable: "code",
    docs: { description: "Ban comments: say it in names, types, tests or a lint rule instead." },
    messages: {
      comment:
        "Comments are banned (AGENTS.md). Put the intent in a name, a type, a test or a lint rule. If an outside constraint truly can't be expressed in code, link the issue in AGENTS.md.",
    },
    schema: [],
  },
  create(context) {
    const sourceCode = context.sourceCode;
    return {
      Program() {
        for (const comment of sourceCode.getAllComments()) {
          if (comment.type === "Shebang") continue;
          if (KEPT.test(comment.value) || (comment.type === "Line" && TRIPLE_SLASH.test(comment.value))) continue;
          const node = sourceCode.getNodeByRangeIndex(comment.range[0]);
          const container = node?.type === "JSXEmptyExpression" ? node.parent : node?.type === "JSXExpressionContainer" && node.expression.type === "JSXEmptyExpression" ? node : null;
          const [start, end] = container ? container.range : comment.range;
          context.report({
            loc: comment.loc,
            messageId: "comment",
            fix: (fixer) => fixer.removeRange(removalRange(sourceCode, start, end)),
          });
        }
      },
    };
  },
};

export default rule;

rules.disable-needs-reason.mjs:
const DIRECTIVE = /^\s*eslint-(disable|disable-line|disable-next-line|enable)\b/;
const EXPIRY = /\(until (\d{4}-\d{2}-\d{2})\)/;

const rule = {
  meta: {
    type: "problem",
    docs: { description: "Lint exceptions need a reason and an expiry date, and fail once expired." },
    messages: {
      missing: "Lint exceptions need a reason and an expiry: `eslint-disable-next-line <rule> -- <why> (until YYYY-MM-DD)`.",
      expired: "This lint exception expired on {{date}}. Fix the code or renew it with a human's approval.",
    },
    schema: [{ type: "object", properties: { today: { type: "string" } }, additionalProperties: false }],
  },
  create(context) {
    const today = context.options[0]?.today ?? new Date().toISOString().slice(0, 10);
    return {
      Program() {
        for (const comment of context.sourceCode.getAllComments()) {
          const match = DIRECTIVE.exec(comment.value);
          if (!match || match[1] === "enable") continue;
          const [, reason = ""] = comment.value.split(/\s--\s/);
          const expiry = EXPIRY.exec(reason);
          if (!reason.replace(EXPIRY, "").trim() || !expiry) context.report({ loc: comment.loc, messageId: "missing" });
          else if (expiry[1] < today) context.report({ loc: comment.loc, messageId: "expired", data: { date: expiry[1] } });
        }
      },
    };
  },
};

export default rule;

rules.no-hex-colors.mjs:
const HEX = /(^|[^\w&])#(?:[0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})(?![\w-])/;

const rule = {
  meta: {
    type: "problem",
    docs: { description: "Colors come from design tokens, never inline hex." },
    messages: { hex: "Use a design token (Tailwind theme color or CSS variable from globals.css), never an inline hex color." },
    schema: [],
  },
  create(context) {
    const check = (node, text) => {
      if (typeof text === "string" && HEX.test(text)) context.report({ node, messageId: "hex" });
    };
    return {
      Literal(node) {
        check(node, node.value);
      },
      TemplateElement(node) {
        check(node, node.value.cooked);
      },
    };
  },
};

export default rule;
